import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.BeforeEach;
import static org.junit.jupiter.api.Assertions.*;

class TrustGenTest {

    Terminal term;
    Terminal term2;

    @BeforeEach
    void init() {
        String rawFile = """
            ^CAR TICKET
            DEPARTURE: Texel, 23-10-2024, 13:15
            ARRIVAL: Vlieland, 23-10-2024, 13:45
            PRICE: 70 euros
            LENGTH: <5meters
            PASSENGER: Swiatek, Iga
            PASSENGER: Zheng, Qinwen
            ^PASSENGER TICKET
            DEPARTURE: Texel, 23-10-2024, 15:15
            ARRIVAL: Terschelling, 23-10-2024, 15:45
            PRICE: 10 euros
            NAME: Verstappen, Max
            ^PASSENGER TICKET
            DEPARTURE: Texel, 24-10-2024, 15:15
            ARRIVAL: Terschelling, 24-10-2024, 15:45
            PRICE: 10 euros
            NAME: Pulling, Abbi
            ^CAR TICKET
            DEPARTURE: Terschelling, 25-10-2024, 13:00
            ARRIVAL: Vlieland, 25-10-2024, 14:00
            PRICE: 130 euros
            LENGTH: >=5meters
            PASSENGER: Sinner, Jannik
            PASSENGER: Alcaraz, Carlos
            PASSENGER: Djokovic, Novak
            ^BIKE TICKET
            DEPARTURE: Terschelling, 25-10-2024, 13:00
            ARRIVAL: Vlieland, 25-10-2024, 14:00
            PRICE: 25 euros
            PASSENGER: Vos, Marianne
            """;
        term = ParseMaster.parseFile(new java.util.Scanner(rawFile));
        term2 = ParseMaster.parseFile(new java.util.Scanner(rawFile));
    }

    @Test
    void trust_startTurnOverRunsInSeparateThread() throws InterruptedException {
        java.util.concurrent.atomic.AtomicReference<Thread> worker = new java.util.concurrent.atomic.AtomicReference<>();
        java.util.concurrent.atomic.AtomicReference<String> result = new java.util.concurrent.atomic.AtomicReference<>();
        Thread thread = term.startTurnOver("Terschelling", "Vlieland", s -> {
            worker.set(Thread.currentThread());
            result.set(s);
        });
        thread.join();
        assertEquals("All tickets in the database for the route Terschelling -> Vlieland combined are worth 155 euros.", result.get());
        assertSame(thread, worker.get());
        assertNotSame(Thread.currentThread(), worker.get());
    }

    @Test
    void trust_startTurnOverReturnsStartedThread() {
        Thread thread = term.startTurnOver("Terschelling", "Vlieland", s -> {});
        assertTrue(thread.isAlive());
        try {
            thread.join();
        } catch (InterruptedException e) {
            fail("Thread was interrupted while joining");
        }
    }

    @Test
    void trust_startTurnOverPrintsCorrectTurnoverMessage() throws InterruptedException {
        java.util.concurrent.atomic.AtomicReference<String> result = new java.util.concurrent.atomic.AtomicReference<>();
        Thread thread = term.startTurnOver("Terschelling", "Vlieland", result::set);
        thread.join();
        assertEquals("All tickets in the database for the route Terschelling -> Vlieland combined are worth 155 euros.", result.get());
    }

    @Test
    void trust_startTurnOverHandlesRouteWithNoTickets() throws InterruptedException {
        java.util.concurrent.atomic.AtomicReference<String> result = new java.util.concurrent.atomic.AtomicReference<>();
        Thread thread = term.startTurnOver("Ameland", "Schiermonnikoog", result::set);
        thread.join();
        assertEquals("All tickets in the database for the route Ameland -> Schiermonnikoog combined are worth 0 euros.", result.get());
    }

    @Test
    void trust_startTurnOverHandlesReverseRoute() throws InterruptedException {
        java.util.concurrent.atomic.AtomicReference<String> result = new java.util.concurrent.atomic.AtomicReference<>();
        Thread thread = term.startTurnOver("Vlieland", "Terschelling", result::set);
        thread.join();
        assertEquals("All tickets in the database for the route Vlieland -> Terschelling combined are worth 0 euros.", result.get());
    }
}
